def build() -> list[dict]:
    packs = []
    for i, row in enumerate(RAW, start=1):
        slug, name_zh, name_en, group, item, fulfill, tagline, pains, kpis, wf, stages, extra = row
        g = GROUPS[group]
        mods = g["modules"]
        saas = list(dict.fromkeys(CORE_SAAS + g["saas"] + extra))
        packs.append(
            {
                "id": slug,
                "code": f"IND-{i:03d}",
                "nameZh": name_zh,
                "nameEn": name_en,
                "group": group,
                "itemType": item,
                "fulfillment": fulfill,
                "tagline": tagline,
                "pains": pains,
                "kpis": kpis,
                "workflow": {"id": slug, "name": wf, "stages": stages},
                "saasReplaced": saas,
                "modules": {
                    "crm": mods["crm"],
                    "erp": {
                        "inventory": mods["inventory"],
                        "manufacturing": mods["manufacturing"],
                        "pos": mods["pos"],
                        "projects": mods["projects"],
                        "batch": mods["batch"],
                    },
                    "funnel": mods["funnel"],
                    "hygiene": mods["hygiene"],
                    "website": mods["website"],
                    "line": mods["line"],
                },
                "sampleLoop": " → ".join(stages),
            }
        )
    if len(packs) != 100:
        raise SystemExit(f"expected 100 packs, got {len(packs)}")
    slugs = [p["id"] for p in packs]
    if len(set(slugs)) != 100:
        raise SystemExit("duplicate slugs")
    return packs


def main() -> None:
    packs = build()
    out = Path("/workspace/web/data/industries.json")
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(packs, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    groups: dict[str, int] = {}
    for p in packs:
        groups[p["group"]] = groups.get(p["group"], 0) + 1
    print(f"wrote {len(packs)} packs to {out}")
    print(groups)


if __name__ == "__main__":
    main()
